pub fn crc7(crc: u8, bit: u8) -> u8 {
    let top: u8 = ((Int::shr(crc, 6) ^ bit) & 1u8);
    return ((Int::shl(crc, 1) & 127u8) ^ if (top != 0u8) { 9u8 } else { 0u8 });
}

pub fn crc16(crc: u16, bit: u8) -> u16 {
    let top: u8 = (((Int::shr(crc, 15) ^ u16::from(bit)) & 1u16) as u8);
    return (Int::shl(crc, 1) ^ if (top != 0u8) { 4129u16 } else { 0u16 });
}

