pub fn voltage_range(code: u8) -> Voltage {
    if (code == 1u8) {
        return Voltage::V2736;
    }
    if (code == 2u8) {
        return Voltage::ReservedLowVoltage;
    }
    if ((code == 4u8) || (code == 8u8)) {
        return Voltage::Reserved;
    }
    return Voltage::NotDefined;
}

